static const char tpl_hist_keyed[] =
    "/* keyed log2 histogram (1024 keys * 64 slots).\n"
    " * The value struct is 512 bytes - too large to put on the BPF\n"
    " * stack (512B limit). We stash a pre-zeroed template in a per-CPU\n"
    " * ARRAY of size 1 and use it for new-key initialization. */\n"
    "struct spnl_hist_struct { __u64 buckets[64]; };\n"
    "\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_HASH);\n"
    "    __type(key, __u64);\n"
    "    __type(value, struct spnl_hist_struct);\n"
    "    __uint(max_entries, 1024);\n"
    "} bpf_hist_keyed SEC(\".maps\");\n"
    "\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);\n"
    "    __type(key, __u32);\n"
    "    __type(value, struct spnl_hist_struct);\n"
    "    __uint(max_entries, 1);\n"
    "} bpf_hist_keyed_zero SEC(\".maps\");\n"
    "\n"
    "static __noinline __s64 spnl_hist_observe_by(__s64 key, __s64 v)\n"
    "{\n"
    "    __u64 k = (__u64)key;\n"
    "    struct spnl_hist_struct *cur = bpf_map_lookup_elem(&bpf_hist_keyed, &k);\n"
    "    if (!cur) {\n"
    "        __u32 zk = 0;\n"
    "        struct spnl_hist_struct *zero =\n"
    "            bpf_map_lookup_elem(&bpf_hist_keyed_zero, &zk);\n"
    "        if (!zero) return 0;\n"
    "        bpf_map_update_elem(&bpf_hist_keyed, &k, zero, BPF_NOEXIST);\n"
    "        cur = bpf_map_lookup_elem(&bpf_hist_keyed, &k);\n"
    "        if (!cur) return 0;\n"
    "    }\n"
    "    __u32 slot = (__u32)spnl_hist_log2(v);\n"
    "    if (slot >= 64) return 0;\n"
    "    __sync_fetch_and_add(&cur->buckets[slot], 1);\n"
    "    return 0;\n"
    "}\n"
    ;

static const char tpl_hist_linear[] =
    "/* linear histogram (256 caller-bucketed slots). */\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_ARRAY);\n"
    "    __type(key, __u32);\n"
    "    __type(value, __u64);\n"
    "    __uint(max_entries, 256);\n"
    "} bpf_hist_lin SEC(\".maps\");\n"
    "\n"
    "static __noinline __s64 spnl_hist_observe_linear(__s64 slot_arg)\n"
    "{\n"
    "    if (slot_arg < 0) return 0;\n"
    "    __u32 slot = (__u32)slot_arg;\n"
    "    if (slot >= 256) slot = 255;\n"
    "    __u64 *cur = bpf_map_lookup_elem(&bpf_hist_lin, &slot);\n"
    "    if (cur) __sync_fetch_and_add(cur, 1);\n"
    "    return 0;\n"
    "}\n"
    ;

static const char tpl_histogram[] =
    "/* per-unit log2 histogram (64 buckets). */\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_ARRAY);\n"
    "    __type(key, __u32);\n"
    "    __type(value, __u64);\n"
    "    __uint(max_entries, 64);\n"
    "} bpf_hist SEC(\".maps\");\n"
    "\n"
    "/* Verifier-safe integer log2: returns floor(log2(v)) clamped to\n"
    " * [0, HISTOGRAM_SLOTS-1]. v<=0 maps to slot 0 so callers don't have\n"
    " * to guard against zero observations (it just over-reports the\n"
    " * smallest bucket). All comparisons are against compile-time\n"
    " * constants so the verifier sees a bounded computation. */\n"
    "static __noinline __s64 spnl_hist_log2(__s64 v)\n"
    "{\n"
    "    __s64 r = 0;\n"
    "    if (v <= 1) return 0;\n"
    "    if (v >= (1LL << 32)) { v >>= 32; r += 32; }\n"
    "    if (v >= (1   << 16)) { v >>= 16; r += 16; }\n"
    "    if (v >= (1   << 8))  { v >>= 8;  r += 8;  }\n"
    "    if (v >= (1   << 4))  { v >>= 4;  r += 4;  }\n"
    "    if (v >= (1   << 2))  { v >>= 2;  r += 2;  }\n"
    "    if (v >= (1   << 1))  { v >>= 1;  r += 1;  }\n"
    "    if (r > 63) r = 63;\n"
    "    return r;\n"
    "}\n"
    "\n"
    "static __noinline __s64 spnl_hist_observe(__s64 v)\n"
    "{\n"
    "    __u32 slot = (__u32)spnl_hist_log2(v);\n"
    "    if (slot >= 64) return 0;  /* verifier hand-holding */\n"
    "    __u64 *cur = bpf_map_lookup_elem(&bpf_hist, &slot);\n"
    "    if (cur) __sync_fetch_and_add(cur, 1);\n"
    "    return 0;\n"
    "}\n"
    ;

static const char tpl_host_ns[] =
    "/* === the initial namespaces (in_host_ns) ===\n"
    " *\n"
    " * \"is this the host namespace\" is a comparison against a number the kernel hands\n"
    " * nobody. Three candidate sources were measured:\n"
    " *\n"
    " *   typed ksym    extern struct nsproxy init_nsproxy __ksym;\n"
    " *                 LOAD_FAIL -- \"not found in kernel BTF\". vmlinux BTF carried\n"
    " *                 334 VARs on the kernel measured and none of them was an init_*.\n"
    " *   untyped ksym  the form below. libbpf resolves it from /proc/kallsyms; the\n"
    " *                 address it baked in matched kallsyms exactly, and the two\n"
    " *                 independent chains (init_nsproxy and init_task->nsproxy) agree.\n"
    " *   userspace     read /proc/1/ns/* at load time and patch .rodata. This is what\n"
    " *                 Tetragon-style agents do, and it is WRONG for the deployment\n"
    " *                 this project cares about: inside a container /proc/1 is the\n"
    " *                 CONTAINER's init, so it reported mnt 4026532237 where the real\n"
    " *                 initial namespace is 4026531832 -- off by a namespace and\n"
    " *                 still a perfectly ordinary inode number.\n"
    " *\n"
    " * Consequences of the ksym form, stated rather than discovered: the symbols are\n"
    " * resolved at LOAD time against the running kernel (so they cannot go stale),\n"
    " * and a kernel that does not export them fails to load with the symbol named.\n"
    " * That needs /proc/kallsyms with real addresses, i.e. root -- which eBPF probes\n"
    " * already require.\n"
    " */\n"
    "extern const void init_nsproxy __ksym;\n"
    "extern const void init_user_ns __ksym;\n"
    "\n"
    "#define SPNL_HOST_NS(member) \\\n"
    "    ((__s64)BPF_CORE_READ((struct nsproxy *)&init_nsproxy, member, ns.inum))\n"
    "#define SPNL_HOST_USER_NS() \\\n"
    "    ((__s64)BPF_CORE_READ((struct user_namespace *)&init_user_ns, ns.inum))\n"
    ;

