static const char tpl_lock_edge[] =
    "/* per-unit lock-order edge map for deadlock detection.\n"
    " * key = {lock_a, lock_b} (a was held when b was acquired). */\n"
    "struct spnl_lock_edge {\n"
    "    __u64 a;\n"
    "    __u64 b;\n"
    "};\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_HASH);\n"
    "    __type(key, struct spnl_lock_edge);\n"
    "    __type(value, __u64);\n"
    "    __uint(max_entries, 65536);\n"
    "} bpf_lock_edges SEC(\".maps\");\n"
    "\n"
    "static __noinline __s64 spnl_lock_edge(__s64 a, __s64 b)\n"
    "{\n"
    "    struct spnl_lock_edge k = {};\n"
    "    k.a = (__u64)a;\n"
    "    k.b = (__u64)b;\n"
    "    __u64 *v = bpf_map_lookup_elem(&bpf_lock_edges, &k);\n"
    "    if (v) {\n"
    "        __sync_fetch_and_add(v, 1);\n"
    "    } else {\n"
    "        __u64 one = 1;\n"
    "        bpf_map_update_elem(&bpf_lock_edges, &k, &one, BPF_NOEXIST);\n"
    "    }\n"
    "    return 0;\n"
    "}\n"
    ;

static const char tpl_map_in_map[] =
    "/* map-in-map. 4 inner ARRAY maps + an\n"
    " * ARRAY_OF_MAPS outer that libbpf populates with them at load time.\n"
    " * The inners must be instances of the SAME named struct that appears in\n"
    " * __array(values, ...): with per-map anonymous struct types the `.values`\n"
    " * initializer is an incompatible-pointer-types diagnostic, which clang >= 22\n"
    " * rejects by default. */\n"
    "struct mim_inner_t {\n"
    "    __uint(type, BPF_MAP_TYPE_ARRAY);\n"
    "    __type(key, __u32);\n"
    "    __type(value, __s64);\n"
    "    __uint(max_entries, 64);\n"
    "};\n"
    "\n"
    "struct mim_inner_t bpf_mim_inner0 SEC(\".maps\");\n"
    "struct mim_inner_t bpf_mim_inner1 SEC(\".maps\");\n"
    "struct mim_inner_t bpf_mim_inner2 SEC(\".maps\");\n"
    "struct mim_inner_t bpf_mim_inner3 SEC(\".maps\");\n"
    "\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_ARRAY_OF_MAPS);\n"
    "    __uint(max_entries, 4);\n"
    "    __type(key, __u32);\n"
    "    __array(values, struct mim_inner_t);\n"
    "} bpf_mim_outer SEC(\".maps\") = {\n"
    "    .values = { &bpf_mim_inner0, &bpf_mim_inner1, &bpf_mim_inner2, &bpf_mim_inner3 },\n"
    "};\n"
    "\n"
    "static __always_inline __s64 spnl_mim_at(__s64 g, __s64 k)\n"
    "{\n"
    "    __u32 gi = (__u32)g;\n"
    "    void *inner = bpf_map_lookup_elem(&bpf_mim_outer, &gi);\n"
    "    if (!inner) return 0;\n"
    "    __u32 ki = (__u32)k;\n"
    "    return (__s64)(unsigned long)bpf_map_lookup_elem(inner, &ki);\n"
    "}\n"
    "static __always_inline __s64 spnl_mim_inc(__s64 g, __s64 k)\n"
    "{\n"
    "    __s64 *v = (__s64 *)(unsigned long)spnl_mim_at(g, k);\n"
    "    if (!v) return 0;\n"
    "    __sync_fetch_and_add(v, 1);\n"
    "    return *v;\n"
    "}\n"
    "static __always_inline __s64 spnl_mim_get(__s64 g, __s64 k)\n"
    "{\n"
    "    __s64 *v = (__s64 *)(unsigned long)spnl_mim_at(g, k);\n"
    "    return v ? *v : 0;\n"
    "}\n"
    ;

static const char tpl_msg_ubuf[] =
    "/* === msghdr -> user buffer, and the datagram's real destination === */\n"
    "\n"
    "/* Every builtin that reads the bytes of a send or a receive starts from a\n"
    " * `struct msghdr *` and has to answer one question: where in user memory are\n"
    " * the bytes? All eleven of them used to answer it the same wrong way --\n"
    " *\n"
    " *     BPF_CORE_READ(msg, msg_iter.__ubuf_iovec.iov_base)\n"
    " *\n"
    " * -- which is only the answer for ITER_UBUF. `msg_iter` is a tagged union and\n"
    " * that member is one of the tags; for ITER_IOVEC the same 8 bytes hold `__iov`,\n"
    " * a pointer to the KERNEL's copy of the caller's iovec array (import_iovec\n"
    " * copies it in), so the read above hands a kernel address to\n"
    " * bpf_probe_read_user, which fails. Measured on a 2-iovec sendmsg: iov_base\n"
    " * reported 0xffff80008714bc88 while the payload the process actually sent was\n"
    " * at 0xffffe6f60fb8.\n"
    " *\n"
    " * A single-entry iovec array is NOT affected: the kernel normalises nr_segs==1\n"
    " * to ITER_UBUF, which is why writev-style sends of one segment worked and why\n"
    " * the bug survived every fixture -- all of them send one buffer.\n"
    " *\n"
    " * The resolution lives in ONE function on purpose. Eleven call sites each\n"
    " * carrying their own union discipline is exactly how a second, disagreeing\n"
    " * table gets written.\n"
    " */\n"
    "\n"
    "/* raw_status when the helper below could not name a user buffer at all. Distinct\n"
    " * from any errno bpf_probe_read_user can return, so a reader never has to guess\n"
    " * which of the two happened. */\n"
    "#define SPNL_RAW_NO_USER_BUFFER (-1)\n"
    "\n"
    "static __noinline void *spnl_msg_ubuf(struct msghdr *msg)\n"
    "{\n"
    "    if (!msg) return (void *)0;\n"
    "    /* The enumerator values are read out of the running kernel's BTF rather\n"
    "     * than baked in, so a renumbered enum cannot silently reclassify a send. */\n"
    "    __u8 it = BPF_CORE_READ(msg, msg_iter.iter_type);\n"
    "    void *base = (void *)0;\n"
    "    if (it == bpf_core_enum_value(enum iter_type, ITER_UBUF)) {\n"
    "        base = BPF_CORE_READ(msg, msg_iter.__ubuf_iovec.iov_base);\n"
    "    } else if (it == bpf_core_enum_value(enum iter_type, ITER_IOVEC)) {\n"
    "        /* __iov always points at the iterator's CURRENT segment (iov_iter_advance\n"
    "         * walks the pointer forward), so the first entry is the right one at any\n"
    "         * position, not just at entry. */\n"
    "        const struct iovec *iov = BPF_CORE_READ(msg, msg_iter.__iov);\n"
    "        if (iov) base = BPF_CORE_READ(iov, iov_base);\n"
    "    }\n"
    "    /* ITER_BVEC / ITER_KVEC / ITER_XARRAY / ITER_DISCARD describe pages or kernel\n"
    "     * memory: there is no user buffer to read, and saying so is the point --\n"
    "     * returning a plausible pointer is what produced the zero-filled records. */\n"
    "    if (!base) return (void *)0;\n"
    "    /* iov_offset is how far into the current segment the iterator already is.\n"
    "     * Zero at every capture point this codegen attaches to (all of them are\n"
    "     * function entries), but reading it makes the contract \"the bytes the\n"
    "     * iterator is about to consume\" true wherever the helper is called. */\n"
    "    return (void *)((__u8 *)base + (unsigned long)BPF_CORE_READ(msg, msg_iter.iov_offset));\n"
    "}\n"
    ;

static const char tpl_off_cpu[] =
    "/* per-unit off-CPU tracking (ts + stack id per pid).\n"
    " * off_cpu_start(pid) records when a task goes off-CPU; off_cpu_observe(pid)\n"
    " * fires when it comes back, bins (stack_id -> total off-CPU ns) via\n"
    " * the keyed hist. */\n"
    "struct spnl_off_cpu_entry {\n"
    "    __u64 ts;\n"
    "    __u32 stack_id;\n"
    "};\n"
    "\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_HASH);\n"
    "    __type(key, __u32);\n"
    "    __type(value, struct spnl_off_cpu_entry);\n"
    "    __uint(max_entries, 10240);\n"
    "} bpf_off_cpu SEC(\".maps\");\n"
    "\n"
    "/* off_cpu_start: capture (ktime_ns, stack_id) for the going-off task.\n"
    " * ctx must be the program's bpf_get_stackid-compatible context. */\n"
    "static __noinline __s64 spnl_off_cpu_start(__u32 pid, void *ctx)\n"
    "{\n"
    "    struct spnl_off_cpu_entry e;\n"
    "    e.ts       = bpf_ktime_get_ns();\n"
    "    e.stack_id = (__u32)bpf_get_stackid(ctx, &bpf_stacks, 0);\n"
    "    bpf_map_update_elem(&bpf_off_cpu, &pid, &e, BPF_ANY);\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "/* off_cpu_observe: if pid has a stored entry, compute delta = now - ts,\n"
    " * bin into the keyed log2 hist under key=stack_id, then drop the\n"
    " * entry. Returns delta ns (or 0 if no entry). */\n"
    "static __noinline __s64 spnl_off_cpu_observe(__u32 pid)\n"
    "{\n"
    "    struct spnl_off_cpu_entry *e =\n"
    "        bpf_map_lookup_elem(&bpf_off_cpu, &pid);\n"
    "    if (!e) return 0;\n"
    "    __u64 delta    = bpf_ktime_get_ns() - e->ts;\n"
    "    __u32 stack_id = e->stack_id;\n"
    "    bpf_map_delete_elem(&bpf_off_cpu, &pid);\n"
    "\n"
    "    /* Inline hist_observe_by(stack_id, delta) - keyed log2 hist. */\n"
    "    __u64 k = (__u64)stack_id;\n"
    "    struct spnl_hist_struct *cur =\n"
    "        bpf_map_lookup_elem(&bpf_hist_keyed, &k);\n"
    "    if (!cur) {\n"
    "        __u32 zk = 0;\n"
    "        struct spnl_hist_struct *zero =\n"
    "            bpf_map_lookup_elem(&bpf_hist_keyed_zero, &zk);\n"
    "        if (!zero) return (__s64)delta;\n"
    "        bpf_map_update_elem(&bpf_hist_keyed, &k, zero, BPF_NOEXIST);\n"
    "        cur = bpf_map_lookup_elem(&bpf_hist_keyed, &k);\n"
    "        if (!cur) return (__s64)delta;\n"
    "    }\n"
    "    __u32 slot = (__u32)spnl_hist_log2((__s64)delta);\n"
    "    if (slot >= 64) return (__s64)delta;\n"
    "    __sync_fetch_and_add(&cur->buckets[slot], 1);\n"
    "    return (__s64)delta;\n"
    "}\n"
    ;

