static const char tpl_timer_map[] =
    "/* bpf_timer-backed periodic callback. Single ARRAY slot\n"
    " * holding the timer struct. The arm prog (also emitted) is fired\n"
    " * once by userspace at load time via bpf_prog_test_run.\n"
    " * Interval: @NS@ ns (compile-time constant). */\n"
    "struct spnl_timer_value {\n"
    "    struct bpf_timer t;\n"
    "};\n"
    "\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_ARRAY);\n"
    "    __uint(max_entries, 1);\n"
    "    __type(key, __u32);\n"
    "    __type(value, struct spnl_timer_value);\n"
    "} spnl_timer_map SEC(\".maps\");\n"
    "\n"
    "/* forward decl for the callback so the arm prog can reference it\n"
    " * before the body is emitted (codegen emits cb after the map). */\n"
    "static int spnl_timer_cb_@NAME@(void *map, int *key, struct spnl_timer_value *v);\n"
    ;

static const char tpl_timer_prog[] =
    "/* bpf_timer callback for on :timer, every: @NS@ ns.\n"
    " * The verifier requires bpf_timer callbacks to return literal 0\n"
    " * (the body's return value is ignored, which matches the Ruby\n"
    " * semantic of `on :timer do ... end` having no return value).\n"
    " *\n"
    " * Re-ported from the retired Ruby code generator, having been lost in the port\n"
    " * to C and withdrawn as unimplemented; the rule was re-measured on 7.1.5:\n"
    " * returning an unknown scalar here still fails with \"At async callback\n"
    " * return the register R0 has unknown scalar value should have been in\n"
    " * [0, 0]\" -- the same verdict recorded on 7.0.x. */\n"
    "static int spnl_timer_cb_@NAME@(void *map, int *key, struct spnl_timer_value *v)\n"
    "{\n"
    "    (void)map; (void)key;\n"
    "@BODY@    bpf_timer_start(&v->t, @NS@ULL, 0);\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "/* The arming program -- fired once by userspace at load time via\n"
    " * bpf_prog_test_run (glue.c _spnl_timer_arm_all fires every program whose\n"
    " * name starts with spnl_timer_arm_).\n"
    " *\n"
    " * `__u64 *ctx` is the original shape. A plain `void *ctx` was measured to also\n"
    " * loads on 7.1.5, so that lesson has expired -- the typed pointer is kept\n"
    " * because it is what the arm program is (libbpf sizes the argument from BTF)\n"
    " * and because changing it would buy nothing. The literal 1 below has NOT\n"
    " * expired: CLOCK_MONOTONIC is still absent from vmlinux.h. */\n"
    "SEC(\"syscall\")\n"
    "int spnl_timer_arm_@NAME@(__u64 *ctx)\n"
    "{\n"
    "    __u32 _k = 0;\n"
    "    struct spnl_timer_value *_v = bpf_map_lookup_elem(&spnl_timer_map, &_k);\n"
    "    if (!_v) return 0;\n"
    "    bpf_timer_init(&_v->t, &spnl_timer_map, 1 /* CLOCK_MONOTONIC */);\n"
    "    bpf_timer_set_callback(&_v->t, spnl_timer_cb_@NAME@);\n"
    "    bpf_timer_start(&_v->t, @NS@ULL, 0);\n"
    "    (void)ctx;\n"
    "    return 0;\n"
    "}\n"
    ;

static const char tpl_udp_dst[] =
    "/* === where this datagram is actually going === */\n"
    "\n"
    "/* `sock_dport(sk)` answers \"what peer is this socket connected to\". For a UDP\n"
    " * send that is only the same question when the socket IS connected. udp_sendmsg\n"
    " * itself makes the distinction first thing it does: an address in msg_name wins,\n"
    " * and only when there is none does it fall back to the connected peer (and\n"
    " * returns -EDESTADDRREQ if there is no peer either).\n"
    " *\n"
    " * A probe written against sock_dport therefore reports nothing at all for an\n"
    " * unconnected sender -- skc_dport is 0, so a `== 53` filter is simply false.\n"
    " * That is not a rare shape: dnsmasq forwards upstream with a bare sendto(),\n"
    " * because one socket serves many destinations. glibc, python, busybox and Go\n"
    " * all connect, which is why every resolver measured up to now came through.\n"
    " *\n"
    " * These two fold the kernel's own rule in, so the author does not have to know\n"
    " * it -- and cannot get it half right, which is what makes the failure silent.\n"
    " *\n"
    " * SEND hooks only. On udp_recvmsg, msg_name is an OUTPUT: the kernel is about\n"
    " * to write the sender's address there, so reading it at entry interprets\n"
    " * uninitialised bytes as a port. The receive side has no equivalent question --\n"
    " * who sent the datagram is not known until the call returns -- so a receive-side\n"
    " * filter really is limited to the socket's connected peer, and that limit is\n"
    " * named rather than papered over.\n"
    " */\n"
    "static __noinline __s64 spnl_udp_dport(struct sock *sk, struct msghdr *msg)\n"
    "{\n"
    "    void *nm = msg ? BPF_CORE_READ(msg, msg_name) : (void *)0;\n"
    "    if (nm) {\n"
    "        /* AF_INET/AF_INET6 are UAPI #defines, not an enum, so there is nothing\n"
    "         * in BTF to relocate against -- unlike the iter_type tags next door. */\n"
    "        __u16 fam = BPF_CORE_READ((struct sockaddr *)nm, sa_family);\n"
    "        if (fam == 2)  return (__s64)(__u16)bpf_ntohs(BPF_CORE_READ((struct sockaddr_in *)nm, sin_port));\n"
    "        if (fam == 10) return (__s64)(__u16)bpf_ntohs(BPF_CORE_READ((struct sockaddr_in6 *)nm, sin6_port));\n"
    "        return 0;\n"
    "    }\n"
    "    if (!sk) return 0;\n"
    "    return (__s64)(__u16)bpf_ntohs(BPF_CORE_READ(sk, __sk_common.skc_dport));\n"
    "}\n"
    "\n"
    "static __noinline __s64 spnl_udp_daddr(struct sock *sk, struct msghdr *msg)\n"
    "{\n"
    "    void *nm = msg ? BPF_CORE_READ(msg, msg_name) : (void *)0;\n"
    "    if (nm) {\n"
    "        __u16 fam = BPF_CORE_READ((struct sockaddr *)nm, sa_family);\n"
    "        if (fam == 2) return (__s64)(__u32)bpf_ntohl(BPF_CORE_READ((struct sockaddr_in *)nm, sin_addr.s_addr));\n"
    "        return 0;   /* AF_INET6 has no IPv4 address to give back; ask sock_daddr6_* */\n"
    "    }\n"
    "    if (!sk) return 0;\n"
    "    return (__s64)(__u32)bpf_ntohl(BPF_CORE_READ(sk, __sk_common.skc_daddr));\n"
    "}\n"
    ;

static const char tpl_user_ringbuf[] =
    "/* USER_RINGBUF for the host-to-kernel command channel.\n"
    " *\n"
    " * The one direction a plain BPF ringbuf cannot go. `bpf_ringbuf_*` carries\n"
    " * kernel->host; this map carries host->kernel, in FIFO order, with the host\n"
    " * side batching through libbpf's reserve/submit (the channel exists to batch).\n"
    " *\n"
    " * Re-ported from the retired Ruby code generator, having been lost in the port\n"
    " * to C; the map type was withdrawn once the audit withdrew both\n"
    " * `user_ringbuf_drain` and the `user_ringbuf__` attach kind.\n"
    " * The declaration below is byte-for-byte the oracle's, and the oracle's whole\n"
    " * output was measured to compile and load unchanged on 7.1.5-ebpf /\n"
    " * clang 19.1.7 / -mcpu=v1.\n"
    " *\n"
    " * TWO NUMBERS LIVE IN TWO FILES HERE and nothing checks them at build time:\n"
    " *   - the map's literal name `bpf_user_cmds`, which the loader's\n"
    " *     `sp_bpf_user_cmd_push` finds by string, and\n"
    " *   - the 8-byte record, which the callback below reads with a fixed\n"
    " *     `sizeof(__s64)` and the loader reserves with a fixed `sizeof(long long)`.\n"
    " * Measured what a disagreement does: a SHORT\n"
    " * record still fires the callback and still counts, but `bpf_dynptr_read`\n"
    " * returns -E2BIG and the value stays 0 -- silently. That is why the shipped\n"
    " * pusher is the only advertised way in, and why `describe` prints the size.\n"
    " *\n"
    " * max_entries is a byte count (ring size), not a record count: 256 KB. */\n"
    "struct {\n"
    "    __uint(type, BPF_MAP_TYPE_USER_RINGBUF);\n"
    "    __uint(max_entries, 262144);\n"
    "} bpf_user_cmds SEC(\".maps\");\n"
    "\n"
    "static long spnl_user_ringbuf_cb_@CB@(struct bpf_dynptr *dynptr, void *_uctx);\n"
    ;

static const char tpl_user_ringbuf_cb[] =
    "/* user_ringbuf callback for user_ringbuf__@CB@ */\n"
    "static long spnl_user_ringbuf_cb_@CB@(struct bpf_dynptr *dynptr, void *_uctx)\n"
    "{\n"
    "    @CTYPE@ @PARAM@ = 0;\n"
    "    bpf_dynptr_read(&@PARAM@, sizeof(@PARAM@), dynptr, 0, 0);\n"
    "    (void)_uctx;\n"
    "@BODY@    return 0;\n"
    "}\n"
    ;

